fn svg_source(name: &str) -> Option<String> {
    let (d, is_fill) = icons().get(name)?;
    let body = if *is_fill {
        format!(
            r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path fill-rule="evenodd" clip-rule="evenodd" d="{}"/></svg>"#,
            d
        )
    } else {
        format!(
            r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="{}"/></svg>"#,
            d
        )
    };
    Some(body)
}

/// 应用内嵌资源（svg 图标）
pub struct EmbeddedAssets;

impl AssetSource for EmbeddedAssets {
    fn load(&self, path: &str) -> gpui::Result<Option<Cow<'static, [u8]>>> {
        if let Some(name) = path.strip_prefix("icons/") {
            if let Some(src) = svg_source(name) {
                return Ok(Some(Cow::Owned(src.into_bytes())));
            }
        }
        Ok(None)
    }

    fn list(&self, _path: &str) -> gpui::Result<Vec<SharedString>> {
        Ok(vec![])
    }
}

/// 渲染图标：`icon("search").size(px(14.)).text_color(...)`
pub fn icon(name: &'static str) -> Svg {
    gpui::svg()
        .path(SharedString::from(format!("icons/{}", name)))
        .into_element()
}
